<?php
if (!defined('ABSPATH')) exit;
final class SEO_Manager_Local_SEO {public static function init():void{}public static function output():void{if(!is_singular()||(int)!seom_get('local_enabled',0))return;$name=seom_get('org_name',get_bloginfo('name'));$d=['@context'=>'https://schema.org','@type'=>seom_get('local_business_type','LocalBusiness'),'name'=>$name,'url'=>home_url('/')];foreach(['local_phone'=>'telephone','local_email'=>'email','local_price_range'=>'priceRange'] as $k=>$s){$v=trim((string)seom_get($k,''));if($v!=='')$d[$s]=$v;}$addr=array_filter(['streetAddress'=>seom_get('local_address',''),'addressLocality'=>seom_get('local_city',''),'addressRegion'=>seom_get('local_state',''),'postalCode'=>seom_get('local_postcode',''),'addressCountry'=>seom_get('local_country','')]);if($addr)$d['address']=array_merge(['@type'=>'PostalAddress'],$addr);$lat=seom_get('local_lat','');$lng=seom_get('local_lng','');if($lat!==''&&$lng!=='')$d['geo']=['@type'=>'GeoCoordinates','latitude'=>(float)$lat,'longitude'=>(float)$lng];echo '<script type="application/ld+json">'.wp_json_encode($d,JSON_UNESCAPED_UNICODE).'</script>' . "\n";}}
